"kind": "propose",
"summary": "Adjust liveness probe initialDelaySeconds and timeoutSeconds to match observed startup duration",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe kills pod during startup due to insufficient initial delay and timeout",
    "supporting": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 30,
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow 30s for app startup, with 5s timeout for health check responses",
  "rationale": "Logs show app ran 32s before being killed (killed_during_startup=true). Initial delay of 10s and timeout of 1s were insufficient for startup and health check. Increasing initialDelaySeconds to 30s matches observed startup duration, while 5s timeout provides reasonable response time after startup.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
